INSERT OR IGNORE INTO sources(id,title,source_type,evidence_tier,institution,author_or_editor,language_id,publication_date,accessed_date,url,catalogue_number,rights_status,source_perspective,access_or_reuse_restrictions,community_permission_required,translation_status,verification_status,notes) VALUES
('source.greek.ieleusis71.phi','I.Eleusis 71 — Decree of the Eleusinians','ACADEMIC_EPIGRAPHIC_DATABASE',3,'Packard Humanities Institute','PHI Greek Inscriptions','lang.grc',NULL,'2026-08-27','https://epigraphy.packhum.org/text/346531','I.Eleusis 71; IG II² 1185','Database terms apply; locators and independent summaries only','Academic digital edition with findspot qualification and concordance','Do not bulk reproduce edition text',0,'Ancient Greek edition metadata; project summary in English/Chinese','URL_SYNTAX_VALID','A fourth-century decree from Eleusis explicitly recorded as not from the sanctuary of Demeter and Kore.'),
('source.greek.ieleusis72.phi','I.Eleusis 72 — Decree honoring Hierokleides','ACADEMIC_EPIGRAPHIC_DATABASE',3,'Packard Humanities Institute','PHI Greek Inscriptions','lang.grc',NULL,'2026-08-27','https://epigraphy.packhum.org/text/346532','I.Eleusis 72','Database terms apply; locators and independent summaries only','Academic digital edition with object description and findspot qualification','Do not bulk reproduce edition text',0,'Ancient Greek edition metadata; project summary in English/Chinese','URL_SYNTAX_VALID','Decree honoring the hierophant Hierokleides; several white-marble stele fragments, not from the sanctuary.'),
('source.greek.sacred_way.efada','Ancient Iera Odos (Sacred Way)','OFFICIAL_ARCHAEOLOGICAL_SITE',3,'Ephorate of Antiquities of West Attica, Hellenic Ministry of Culture','Ephorate of Antiquities of West Attica','lang.en',NULL,'2026-08-27','https://www.efada.gr/en-us/Archaeological-Sites-Monuments/-Catalogue-of-Sites-Monuments/ancient-iera-odos-sacred-way-municipalities-of-egaleo-chaidari-aspropyrgos-elefsina','Iera Odos site catalogue','Official site terms apply; metadata and independent summaries only','Regional archaeological authority describing route segments and monuments','Do not package images',0,'Official English page','URL_SYNTAX_VALID','Records the route, Aphrodite sanctuary and Hadrianic bridge as distinct archaeological components.'),
('source.greek.eleusis_acropolis_exhibition2018','Eleusis: The Great Mysteries','MUSEUM_EXHIBITION_RECORD',3,'Acropolis Museum / Ephorate of Antiquities of West Attica','Acropolis Museum','lang.en','2018','2026-08-27','https://www.theacropolismuseum.gr/en/temporary-exhibitions/eleusis-great-mysteries','Temporary exhibition, 2018','Museum page terms apply; metadata and independent summaries only','Modern exhibition connecting Eleusis, the Athens Eleusinion, Sacred Way and objects','Do not treat exhibition design as ancient ritual evidence',0,'Official English museum page','URL_SYNTAX_VALID','Useful for network context; the reconstructed darkened Anaktoron in the exhibition remains modern interpretation.');

