INSERT OR IGNORE INTO evidence(id,claim_id,source_id,source_location,catalogue_number,evidence_type,direction,strength,research_notes)
SELECT 'evidence.'||substr(c.id,7),c.id,
 CASE
  WHEN c.id LIKE 'claim.v0170.ninnion_%' THEN 'source.greek.eleusinian_relief.nam126'
  WHEN c.id LIKE 'claim.v0170.i71_%' THEN 'source.greek.ieleusis71.phi'
  WHEN c.id LIKE 'claim.v0170.i72_%' THEN 'source.greek.ieleusis72.phi'
  WHEN c.id LIKE 'claim.v0170.aphrodite_%' OR c.id LIKE 'claim.v0170.bridge_%' THEN 'source.greek.sacred_way.efada'
  WHEN c.id='claim.v0170.telesterion_phases' THEN 'source.greek.eleusis.efada'
  WHEN c.id='claim.v0170.reliefnetwork_metcopy' THEN 'source.greek.eleusinian_relief.met141309'
  ELSE 'source.greek.eleusinian_relief.nam126' END,
 CASE WHEN c.id LIKE 'claim.v0170.i71_%' THEN 'I.Eleusis 71 metadata and findspot note'
      WHEN c.id LIKE 'claim.v0170.i72_%' THEN 'I.Eleusis 72 metadata and findspot note'
      ELSE 'Official object, site or museum record cited in claim notes' END,
 NULL,
 CASE WHEN c.knowledge_layer='TEXTUAL_WITNESS' THEN 'INSCRIPTION' WHEN c.knowledge_layer='ARCHAEOLOGICAL' THEN 'ARCHAEOLOGICAL' ELSE 'MODERN_SCHOLARSHIP' END,
 'SUPPORTS',c.confidence,'v0.17 source-located evidence; no restricted ritual content reproduced'
FROM claims c WHERE c.id LIKE 'claim.v0170.%';

